def reviewed_current330(hass,transport,iid):
 # A Core identifier and its bound SDK/Trial identifier are different namespaces.
 display=hass.data.get('cloudpelizzon_profile229')
 if display is None or getattr(display,'closed',True):return False
 context=getattr(display,'context',{});claim=getattr(display,'cached',None)
 return bool(isinstance(context,dict) and context.get('client') is getattr(transport.port,'client',None) and context.get('client') is not None and context.get('trial_id')==iid and type(context.get('core_id')) is str and re.fullmatch('[a-f0-9]{32}',context['core_id']) is not None and isinstance(claim,dict) and claim.get('installation_id')==iid and claim.get('core_id')==context.get('core_id') and type(claim.get('issued_at')) in (int,float) and type(claim.get('expires_at')) in (int,float) and claim['issued_at']-2<=time.time()<claim['expires_at'])

async def reviewed330(hass,transport,iid):
 if reviewed_current330(hass,transport,iid):return True
 display=hass.data.get('cloudpelizzon_profile229')
 if display is None or getattr(display,'closed',True):return False
 await display.profile()  # Existing verifier authenticates the signed Core/SDK binding.
 return reviewed_current330(hass,transport,iid)

class DetailFailure330(PermissionError):
 def __init__(self,stage):self.stage=stage;super().__init__('lighting_detail_'+stage)

async def detail_phase330(stage,operation):
 try:return await operation
 except asyncio.CancelledError:raise
 except Exception:raise DetailFailure330(stage) from None

def mirror_target328(hass,eid):
 from homeassistant.helpers import entity_registry as er
 state=hass.states.get(eid);attrs=getattr(state,'attributes',{}) or {}
 row=er.async_get(hass).async_get(eid)
 return bool(attrs.get('mirror_source')=='production_observer' or (row and row.platform=='cloudpelizzon_homolog_mirror'))

def mirror_ready328(hass,eid):
 try:
  from .homolog_mirror.source132 import observer
  from homeassistant.helpers import entity_registry as er
  m=observer(hass);state=hass.states.get(eid);attrs=getattr(state,'attributes',{}) or {}
  row=er.async_get(hass).async_get(eid)
  return bool(m.forward_commands and eid in m.owned and eid not in m.blocked and row and row.platform=='cloudpelizzon_homolog_mirror' and row.config_entry_id==m.entry.entry_id and attrs.get('mirror_source')=='production_observer' and attrs.get('mirror_original_entity_id')==eid and attrs.get('cloudpelizzon_forward_commands') is True and attrs.get('cloudpelizzon_read_only') is False)
 except Exception:return False

def read_only_observation(hass,eid):
 state=hass.states.get(eid);attrs=getattr(state,'attributes',{}) or {}
 return attrs.get('cloudpelizzon_read_only') is True or (mirror_target328(hass,eid) and not mirror_ready328(hass,eid))


def features330(eid,attrs):
 modes=attrs.get('supported_color_modes',[])
 modes=set(modes) if isinstance(modes,(list,tuple)) and all(type(x) is str for x in modes) else set()
 native=eid.startswith('light.')
 return {'brightness':native and bool(modes & {'brightness','color_temp','white','hs','xy','rgb','rgbw','rgbww'}),
         'rgb':native and bool(modes & {'hs','xy','rgb','rgbw','rgbww'}),
         'temperature':native and 'color_temp' in modes and type(attrs.get('min_color_temp_kelvin')) is int and type(attrs.get('max_color_temp_kelvin')) is int and 1000<=attrs['min_color_temp_kelvin']<attrs['max_color_temp_kelvin']<=10000}

def parameters330(eid,action,params,attrs):
 if type(params) is not dict or set(params)-{'brightness_pct','rgb_color','color_temp_kelvin'}:raise PermissionError('invalid_light_parameters')
 if params and action!='turn_on':raise PermissionError('invalid_light_parameters')
 f=features330(eid,attrs)
 if 'brightness_pct' in params and (not f['brightness'] or type(params['brightness_pct']) is not int or not 1<=params['brightness_pct']<=100):raise PermissionError('brightness_not_supported')
 if 'rgb_color' in params:
  rgb=params['rgb_color']
  if not f['rgb'] or type(rgb) is not list or len(rgb)!=3 or any(type(v) is not int or not 0<=v<=255 for v in rgb):raise PermissionError('rgb_not_supported')
 if 'color_temp_kelvin' in params:
  k=params['color_temp_kelvin']
  if not f['temperature'] or type(k) is not int or not attrs['min_color_temp_kelvin']<=k<=attrs['max_color_temp_kelvin']:raise PermissionError('temperature_not_supported')
 if 'rgb_color' in params and 'color_temp_kelvin' in params:raise PermissionError('exclusive_color_modes_required')
 return json.loads(json.dumps(params))

def observed330(row,action,params):
 if row.get('state')!=('on' if action=='turn_on' else 'off'):return False
 attrs=row.get('attributes',{})
 if 'brightness_pct' in params:
  v=attrs.get('brightness')
  if type(v) is not int or not 0<=v<=255 or abs(v-round(params['brightness_pct']*255/100))>4:return False
 if 'rgb_color' in params:
  v=attrs.get('rgb_color')
  if attrs.get('color_mode') not in ('rgb','rgbw','rgbww','hs','xy'):return False
  if not isinstance(v,(list,tuple)) or len(v)!=3 or any(type(x) not in (int,float) or not 0<=x<=255 for x in v) or any(abs(a-b)>8 for a,b in zip(v,params['rgb_color'])):return False
 if 'color_temp_kelvin' in params:
  v=attrs.get('color_temp_kelvin')
  if attrs.get('color_mode')!='color_temp':return False
  if type(v) is not int or abs(v-params['color_temp_kelvin'])>100:return False
 return True

def details330(eid,row):
 attrs=row.get('attributes',{});f=features330(eid,attrs)
 out={'entity_id':eid,'state':row.get('state'),'features':f}
 for key in ('brightness','color_temp_kelvin','min_color_temp_kelvin','max_color_temp_kelvin'):
  v=attrs.get(key)
  if type(v) is int and 0<=v<=10000:out[key]=v
 rgb=attrs.get('rgb_color')
 if isinstance(rgb,(list,tuple)) and len(rgb)==3 and all(type(v) in (int,float) and 0<=v<=255 for v in rgb):out['rgb_color']=[round(v) for v in rgb]
 return out

def suggested_room(name):
 text=unicodedata.normalize('NFKD',name).encode('ascii','ignore').decode().lower()
 # A suggestion only, never silently inferred or written to the HA registry.
 patterns=[(r'\bsala\s+(?:de\s+)?jantar\b','Sala de Jantar'),(r'\bsala\s+(?:de\s+)?estar\b','Sala de Estar'),
  (r'\bhall\s+(?:de\s+)?entrada\b','Hall de Entrada'),(r'\bgaragem\b','Garagem'),
  (r'\bcozinha\b','Cozinha'),(r'\blavanderia\b','Lavanderia'),(r'\bescritorio\b','Escritório'),
  (r'\bjardim\b','Jardim'),(r'\bvaranda\b','Varanda'),(r'\bquintal\b','Quintal')]
 hits={label for pattern,label in patterns if re.search(pattern,text)}
 return next(iter(hits)) if len(hits)==1 else None

class RoomSuggestions(Sync):
 def __init__(self,hass):
  super().__init__(hass);self.previews={};self.applying=ContextVar('room_review240',default=False)
 async def inspect(self,connection,transport,user,iid):
  source,ignored,config,_=await super().inspect(connection,transport,user,iid)
  digest=hashlib.sha256(json.dumps(source,sort_keys=True,ensure_ascii=False).encode()).hexdigest()
  key=(id(connection),user.id)
  if self.applying.get():
   old=self.previews.get(key)
   if old is None or old[0]!=digest or time.monotonic()-old[1]>600:raise PermissionError('room_preview_changed')
  self.current_digest=digest
  self.suggestions=[]
  assigned={v['entity_id'] for v in config['items'] if v['room_id'] is not None}
  for row in source:
   if row['area_id'] is not None or row['entity_id'] in assigned:continue
   name=suggested_room(row['name'])
   if name:
    row['area_id']='suggestion240_'+hashlib.sha256(name.encode()).hexdigest()[:20]
    row['area_name']=name
    self.suggestions.append({'entity_id':row['entity_id'],'name':row['name'],'room':name})
  return source,ignored,config,plan(source,config)
 async def run(self,*a,**kw):
  token=self.applying.set(kw.get('mutate',False))
  try:report=await super().run(*a,**kw)
  finally:self.applying.reset(token)
  if report.get('state')!='busy' and not kw.get('mutate',False):
   if len(self.previews)>128:self.previews.clear()
   self.previews[(id(a[0]),a[0].user.id)]=(self.current_digest,time.monotonic())
  return {**report,'suggestions':getattr(self,'suggestions',[]),'ha_registry_altered':False}

"""User-confirmed relay mapping through native revision-checked configuration only."""

class Controls:
 def __init__(self,hass):
  from homeassistant.helpers.storage import Store
  self.hass=hass;self.lock=asyncio.Lock();self.closed=False
  self.store=Store(hass,1,'cloudpelizzon_lighting_commands240')
 async def dispatch_mirror328(self,connection,user,transport,iid,eid,action,snapshot,local,expires,params=None):
  params=params or {}
  from .homolog_mirror.source132 import observer,source_state,post_service,DELIVERY_CHECK
  from homeassistant.auth.permissions.const import POLICY_CONTROL
  if not await reviewed330(self.hass,transport,iid) or not mirror_ready328(self.hass,eid):raise PermissionError('production_target_not_authorized')
  mirror=observer(self.hass)
  before=await source_state(mirror,eid)
  parameters330(eid,action,params,before.get('attributes',{}))
  if before['state'] not in ('on','off') or before.get('attributes',{}).get('mirror_source')=='production_observer':raise PermissionError('production_entity_unavailable')
  # Authorization for module access is distinct from the native user's control ACL.
  fresh=await transport.scope.snapshot(connection)
  if any(fresh.get(k)!=snapshot.get(k) for k in ('configuration','grant')):raise PermissionError('entitlement_or_configuration_changed')
  current=await self.current(connection,user,transport,iid,eid)
  deadline=time.monotonic()+0.5
  def check():
   if (time.monotonic()>=deadline or self.closed or transport.closed or connection.user is not user or getattr(connection,'closed',False) or not current.is_active or getattr(current,'system_generated',False) or transport.port.installation_id()!=iid or not transport.port.registration_ready() or not reviewed_current330(self.hass,transport,iid) or observer(self.hass) is not mirror or not mirror_ready328(self.hass,eid)):raise PermissionError('delivery_session_changed')
   if not current.is_admin and not current.permissions.check_entity(eid,POLICY_CONTROL):raise PermissionError('control_permission_required')
   if local is not None and not local.control_current(expires):raise PermissionError('paid_lighting_access_expired')
  check()
  mirror.last_command={'entity_id':eid,'service':eid.split('.')[0]+'.'+action,'source':mirror.source.split('/api/')[0],'outcome':'checking','at':time.time(),'module':'CP-LIGHTING','before':before['state']}
  context=DELIVERY_CHECK.set(check)
  try:await post_service(mirror,eid.split('.')[0],action,{'entity_id':eid,**params})
  finally:DELIVERY_CHECK.reset(context)
  mirror.commands_forwarded+=1;mirror.last_command['outcome']='accepted_not_verified';mirror.status('connected')
  until=time.monotonic()+8;expected='on' if action=='turn_on' else 'off'
  while True:
   after=await source_state(mirror,eid);mirror.apply(after);mirror.last_command['after']=after['state']
   if observed330(after,action,params):
    mirror.last_command['outcome']='already_in_state' if before['state']==expected else 'state_verified';mirror.status('connected');return
   if time.monotonic()>=until:break
   await asyncio.sleep(.5)
  mirror.last_command['outcome']='no_state_change';mirror.status('connected')
  raise PermissionError('production_state_not_confirmed_no_retry')

 async def current(self,connection,user,transport,iid,eid):
  from homeassistant.auth.permissions.const import POLICY_CONTROL
  current=await self.hass.auth.async_get_user(user.id)
  if (self.closed or connection.user is not user or getattr(connection,'closed',False) or current is None
      or not current.is_active or getattr(current,'system_generated',False) or transport.closed
      or transport.port.installation_id()!=iid or not transport.port.registration_ready()):
   raise PermissionError('session_changed')
  if not current.is_admin and not current.permissions.check_entity(eid,POLICY_CONTROL):
   raise PermissionError('control_permission_required')
  if read_only_observation(self.hass,eid):raise PermissionError('read_only_observation')
  return current
 async def profile(self,connection):
  transport=self.hass.data.get('cloudpelizzon_lighting_native_v1')
  user=connection.user
  if user is None or not user.is_active or getattr(connection,'closed',False) or transport is None or transport.closed:raise PermissionError('native_transport_required')
  snapshot=await transport.scope.snapshot(connection)
  if connection.user is not user:raise PermissionError('session_changed')
  reviewed=user.is_admin and await reviewed330(self.hass,transport,transport.port.installation_id())
  if connection.user is not user or not user.is_active or getattr(connection,'closed',False):raise PermissionError('session_changed')
  return {'light_controls':{eid:{**features330(eid,v.get('attributes',{})),'rgb_color':details330(eid,{'attributes':getattr(self.hass.states.get(eid),'attributes',{}) or {}}).get('rgb_color')} for eid,v in snapshot.get('states',{}).items()},'read_only_entities':[v['entity_id'] for v in snapshot['configuration']['items'] if v.get('visible') is True and read_only_observation(self.hass,v['entity_id'])],'reviewed_relays322':False}
 async def details(self,connection,eid):
  if type(eid) is not str or not re.fullmatch(r'light\.[a-z0-9_]{1,128}',eid):raise PermissionError('invalid_command')
  user=connection.user;transport=self.hass.data.get('cloudpelizzon_lighting_native_v1')
  if user is None or transport is None:raise PermissionError('native_transport_required')
  iid=transport.port.installation_id();await detail_phase330('session',self.current(connection,user,transport,iid,eid))
  snap=await detail_phase330('snapshot',transport.scope.snapshot(connection))
  item=next((v for v in snap['configuration']['items'] if v['entity_id']==eid),None)
  if item is None or item.get('visible') is not True or item.get('kind')!='light':raise PermissionError('mapped_light_required')
  state=self.hass.states.get(eid)
  row={'state':getattr(state,'state',None),'attributes':dict(getattr(state,'attributes',{}) or {})}
  if mirror_target328(self.hass,eid):
   from .homolog_mirror.source132 import observer,source_state
   if not await detail_phase330('binding',reviewed330(self.hass,transport,iid)) or not mirror_ready328(self.hass,eid):raise DetailFailure330('binding')
   row=await detail_phase330('source',source_state(observer(self.hass),eid))
  fresh=await detail_phase330('revalidation',transport.scope.snapshot(connection))
  await detail_phase330('session',self.current(connection,user,transport,iid,eid))
  if any(fresh.get(k)!=snap.get(k) for k in ('configuration','grant')):raise PermissionError('entitlement_or_configuration_changed')
  return details330(eid,row)

 async def run(self,connection,msg):
  from homeassistant.core import Context
  eid=msg['entity_id'];action=msg['action'];rid=msg['request_id'];params=msg.get('parameters',{})
  if not re.fullmatch(r'(?:light|switch)\.[a-z0-9_]{1,128}',eid) or action not in ('turn_on','turn_off') or not re.fullmatch(r'[a-f0-9]{32}',rid):raise PermissionError('invalid_command')
  user=connection.user;transport=self.hass.data.get('cloudpelizzon_lighting_native_v1')
  if user is None or transport is None:raise PermissionError('native_transport_required')
  if self.lock.locked():return {'state':'busy','message':'Outro comando está em andamento.'}
  async with self.lock:
   iid=transport.port.installation_id()
   await self.current(connection,user,transport,iid,eid)
   # Native scope obtains fresh signed proofs and rechecks entitlement/actor.
   snapshot=await transport.scope.snapshot(connection)
   config=snapshot['configuration'];grant=snapshot['grant']
   paid=grant.get('license',{}).get('allowed') is True
   local=self.hass.data.get('cloudpelizzon_local_lighting296') if paid else None
   if paid and (local is None or not local.matches(iid)):
    raise PermissionError('licensed_module_requires_local_installation')
   item=next((v for v in config['items'] if v['entity_id']==eid),None)
   if (item is None or item.get('visible') is not True or
       (eid.startswith('light.') and item.get('kind')!='light') or
       (eid.startswith('switch.') and item.get('kind')!='light')):
    raise PermissionError('mapped_light_required')
   state=self.hass.states.get(eid)
   if state is None or state.state not in ('on','off'):raise PermissionError('entity_unavailable')
   params=parameters330(eid,action,params,getattr(state,'attributes',{}) or {})
   await self.current(connection,user,transport,iid,eid)
   ledger=await self.store.async_load() or {'installation_id':iid,'requests':{}}
   if ledger['installation_id']!=iid:raise PermissionError('ledger_installation_changed')
   binding=hashlib.sha256(json.dumps([iid,user.id,eid,action]+([params] if params else []),separators=(',',':')).encode()).hexdigest()
   if rid in ledger['requests']:
    if ledger['requests'][rid]['binding']!=binding:raise PermissionError('request_binding_changed')
    return {'state':'already_attempted','message':'Este comando já foi processado ou ficou sem confirmação. Atualize a leitura; não houve reenvio.'}
   if len(ledger['requests'])>=10000:raise PermissionError('command_ledger_review_required')
   ledger['requests'][rid]={'binding':binding,'state':'reserved'}
   await self.store.async_save(ledger)
   await self.current(connection,user,transport,iid,eid)
   fresh=await transport.port.issue_grant(iid,user.id,'lighting.config.read')
   if fresh!=grant:raise PermissionError('entitlement_changed')
   await self.current(connection,user,transport,iid,eid)
   state=self.hass.states.get(eid)
   if state is None or state.state not in ('on','off'):raise PermissionError('entity_unavailable')
   expires=None
   if paid:
    # Paid receipt checks module access. Native HA ACL above grants control.
    expires=await local.authorize_native_control(connection,user,iid,eid,action,rid)
    await self.current(connection,user,transport,iid,eid)
    if not local.control_current(expires):raise PermissionError('paid_lighting_access_expired')
   try:
    parameters330(eid,action,params,getattr(self.hass.states.get(eid),'attributes',{}) or {})
    if mirror_target328(self.hass,eid):
     await self.dispatch_mirror328(connection,user,transport,iid,eid,action,snapshot,local,expires,params)
    else:
     await self.hass.services.async_call(eid.split('.')[0],action,{'entity_id':eid,**params},blocking=True,context=Context(user_id=user.id))
   except asyncio.CancelledError:raise
   except Exception:
    return {'state':'uncertain','message':'O HA não confirmou a execução. Atualize a leitura antes de tentar novamente.'}
   ledger['requests'][rid]['state']='service_completed';await self.store.async_save(ledger)
   # A service completing does not prove that the physical lamp changed state.
   state=self.hass.states.get(eid);target='on' if action=='turn_on' else 'off'
   confirmed=state is not None and observed330({'state':state.state,'attributes':getattr(state,'attributes',{}) or {}},action,params)
   if params and mirror_target328(self.hass,eid):confirmed=True  # Source values were verified by dispatch_mirror328, never by a fabricated mirror value.
   return {'state':'confirmed' if confirmed else 'awaiting_state',
    'message':'Ajuste confirmado pelo HA de origem.' if confirmed and params else 'Estado confirmado pelo HA.' if confirmed else 'Comando enviado. Aguardando atualização da entidade no HA.'}

