def fixture_image337(raw):
 import io,base64
 from PIL import Image,ImageOps
 if len(raw)>1500000:raise ValueError('image_too_large')
 with Image.open(io.BytesIO(raw)) as source:
  if source.format not in ('JPEG','PNG','WEBP') or source.width*source.height>20000000:raise ValueError('invalid_fixture_image')
  image=ImageOps.exif_transpose(source).convert('RGBA');image.thumbnail((640,640))
  background=Image.new('RGBA',image.size,'#10202c');background.alpha_composite(image);image=background.convert('RGB')
  for quality in (85,72,55):
   output=io.BytesIO();image.save(output,'WEBP',quality=quality)
   if len(output.getvalue())<=150000:break
  else:raise ValueError('image_too_large')
 data=output.getvalue();return {'digest':hashlib.sha256(data).hexdigest(),'data':'data:image/webp;base64,'+base64.b64encode(data).decode()}


