 if len(raw)>10*1024*1024:raise ValueError('image_too_large')
 with Image.open(io.BytesIO(raw)) as source:
  if source.format not in ('JPEG','PNG','WEBP','GIF') or source.width*source.height>20000000:raise ValueError('invalid_room_image')
