def picture_path333(value):
 from urllib.parse import urlsplit,unquote
 if not isinstance(value,str) or len(value)>512:return None
 url=urlsplit(value)
 if url.scheme or url.netloc or url.query or url.fragment:return None
 path=unquote(url.path)
 if any(p in ('.','..') for p in path.split('/')) or '\\' in path:return None
 if re.fullmatch(r'/api/image/serve/[a-f0-9]{32}/(?:original|(?:256|512)x(?:256|512)(?:-[a-zA-Z0-9_.-]+)?)',path):return path
 if re.fullmatch(r'/local/[a-zA-Z0-9_/ .-]+\.(?:jpg|jpeg|png|webp|gif)',path,re.I):return path
 return None

def ha_projection333(areas,entities,devices,allowed,admin):
 area_map={r['area_id']:r for r in areas if isinstance(r,dict) and isinstance(r.get('area_id'),str) and isinstance(r.get('name'),str) and 0<len(r['name'])<=80}
 device_map={r['id']:r.get('area_id') for r in devices if isinstance(r,dict) and isinstance(r.get('id'),str)}
 refs={aid:'ha_'+hashlib.sha256(aid.encode()).hexdigest()[:24] for aid in area_map}
 assignments={}
 for row in entities:
  if not isinstance(row,dict) or row.get('entity_id') not in allowed:continue
  aid=row.get('area_id') or device_map.get(row.get('device_id'))
  assignments[row['entity_id']]=refs.get(aid)
 visible=set(assignments.values())
 rooms=[{'id':refs[aid],'name':row['name'],'picture':picture_path333(row.get('picture'))} for aid,row in area_map.items() if admin or refs[aid] in visible]
 if len(rooms)>200:raise PermissionError('room_limit')
 return sorted(rooms,key=lambda x:x['name'].casefold()),assignments

